-- PT102-S2-Q12. Batch 04.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch04$PT102-S2-Q12$batch04$ AND q.stimulus=$batch04$It has long been thought that lizards evolved from a group of amphibians called anthracosaurs, no fossils of which have been found in any rocks older than 300 million years. However, a fossil of a lizard was recently found that is estimated to be 340 million years old. Lizards could not have evolved from creatures that did not exist until after the first lizards. Therefore, lizards could not have evolved from anthracosaurs.$batch04$ AND q.prompt=$batch04$An assumption made in the argument is that there are no$batch04$ AND q.correct_choice=$batch04$A$batch04$) THEN RAISE EXCEPTION 'Question changed: PT102-S2-Q12'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch04$PT102-S2-Q12$batch04$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT102-S2-Q12'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch04$PT102-S2-Q12$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch04$Conclusion$batch04$, $batch04$Lizards could not have evolved from anthracosaurs.$batch04$), (1, $batch04$Evidence$batch04$, $batch04$No anthracosaur fossils have been found in rocks older than 300 million years. A lizard fossil has been found that is about 340 million years old. Lizards cannot have evolved from creatures that came after them.$batch04$), (2, $batch04$Evaluate$batch04$, $batch04$The argument moves from "no anthracosaur fossils *found* older than 300 million years" to "anthracosaurs did not exist before then." Not finding a fossil is not the same as the animal not existing. Older anthracosaur fossils might be out there undiscovered.$batch04$), (3, $batch04$Goal$batch04$, $batch04$A defender: there are no undiscovered anthracosaur fossils old enough to come before the first lizards.$batch04$)) v(position,label,body) WHERE q.qid=$batch04$PT102-S2-Q12$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch04$A$batch04$, $batch04$Negate it: there *are* unknown anthracosaur fossils older than 340 million years. Then anthracosaurs existed before this lizard, and lizards could have evolved from them. The conclusion falls apart.$batch04$), ($batch04$B$batch04$, $batch04$Older lizard fossils would only push lizards back further, which helps the argument. The author does not need to rule them out.$batch04$), ($batch04$C$batch04$, $batch04$The stimulus already gives us a known lizard fossil older than every known anthracosaur fossil. The author is not assuming there are none.$batch04$), ($batch04$D$batch04$, $batch04$Known anthracosaur fossils can be older than some younger lizard fossils. What matters is the first lizard, and nothing known is older than it.$batch04$), ($batch04$E$batch04$, $batch04$Lizard fossils of uncertain age do not affect the argument, which rests on the dated 340-million-year-old fossil.$batch04$)) v(letter,body) WHERE q.qid=$batch04$PT102-S2-Q12$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
